// Simple endless runner based on IDEA.md
// Targets <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.clientWidth || 800);
  const H = (canvas.height = canvas.clientHeight || 600);

  // ----- Ship -----
  const ship = {
    x: W / 2,
    y: H * 0.8,
    r: 15,
    angle: 0, // radians
    vx: 0,
    vy: 0,
    thrust: 0.1,
    rotateSpeed: 0.07,
  };

input.oldString:
function drawStars() {
    ctx.fillStyle = '#fff';
    for (const s of stars) ctx.fillRect(s.x, s.y, s.size, s.size);
  }

input.newString:
function drawStars() {
    // draw glowing stars as circles
    for (const s of stars) {
      const gradient = ctx.createRadialGradient(s.x, s.y, 0, s.x, s.y, s.size);
      gradient.addColorStop(0, 'rgba(255,255,255,0.9)');
      gradient.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);
      ctx.fill();
    }
  }

